(function(C){C["20a"]=(C["20a"]||[]).concat([{"q": "What is an isometry?", "a": "a move f with d(f(P), f(Q)) = d(P, Q) for all P and Q", "w": ["a move with d(f(P), P) the same for all P", "a move that keeps some distances", "a move that leaves the origin in place"], "why": "Every distance, for every pair of points. A slide moves the origin and is an isometry."}, {"q": "Are all rectangles similar?", "a": "no: a similarity keeps the ratio of the sides", "w": ["no: only those with equal areas are", "yes, as all circles are", "yes"], "why": "A 1 by 2 and a 1 by 3 rectangle differ in that ratio."}, {"q": "An isometry is a similarity with which factor?", "a": "1", "w": ["any k > 0", "0", "2"], "why": "d(f(P), f(Q)) = 1 · d(P, Q)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20b"]=(C["20b"]||[]).concat([{"q": "f is a similarity with the factor k. Which factor has f⁻¹?", "a": "1/k", "w": ["k", "−k", "1 − k"], "why": "Factors multiply, and f⁻¹ after f does nothing, with the factor 1."}, {"q": "f keeps every distance. Does f⁻¹?", "a": "yes, always", "w": ["only when f is a slide", "only when f undoes itself", "no"], "why": "Undo-keeps: put f⁻¹(P) and f⁻¹(Q) into f, which keeps their distance, and you get P and Q back."}, {"q": "Do isometries turn about?", "a": "not in general: the order can matter", "w": ["yes", "yes: only similarities do not", "no: no two of them do"], "why": "Slide right by 1 and then flip across the line x = 0: (0, 0) goes to (−1, 0). In the other order it goes to (1, 0)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20c"]=(C["20c"]||[]).concat([{"q": "Which points does the flip across a line ℓ leave in place?", "a": "exactly the points of ℓ", "w": ["only the origin", "none", "every point"], "why": "Each other point P goes to the point P′ for which ℓ is the line of points equally far from P and P′."}, {"q": "Where does the turn by (a, b) send (1, 0) and (0, 1)?", "a": "to (a, b) and (−b, a)", "w": ["to (a, b) and (b, a)", "to (a, b) and (b, −a)", "to (a, −b) and (b, a)"], "why": "(−b, a) is the point a quarter turn on from (a, b)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20d"]=(C["20d"]||[]).concat([{"q": "Two four-sided figures have their sides equal in pairs. Are they congruent?", "a": "not always: take a square and a pushed-over rhombus with sides 1", "w": ["yes", "no: never", "yes, by the count of the sides"], "why": "Their diagonals differ, and an isometry keeps every distance."}, {"q": "S ≅ T and T ≅ U. Why is S ≅ U?", "a": "an isometry after an isometry is an isometry", "w": ["an isometry undoes itself", "T is the same set as S", "every two figures are congruent"], "why": "If f(S) = T and g(T) = U then g(f(S)) = U, and g ∘ f keeps every distance."}, {"q": "Two rectangles have equal areas. Are they congruent?", "a": "not always: take a 1 by 4 and a 2 by 2", "w": ["no: never", "yes", "yes, if their sides are whole numbers"], "why": "Equal areas, different sides, and an isometry keeps every length."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20e"]=(C["20e"]||[]).concat([{"q": "Two flips across lines that cross: what do they make?", "a": "a turn about the crossing point", "w": ["a slide", "a flip", "nothing: they cancel"], "why": "Crossing-flips. Each flip leaves the crossing point in place, so the two together do."}, {"q": "How is a slide by v made of two flips?", "a": "across two lines at right angles to v, half of |v| apart", "w": ["it cannot be made", "across two lines along v, |v| apart", "across two lines at right angles to v, |v| apart"], "why": "Parallel flips slide by twice the gap."}, {"q": "Can two flips make a flip?", "a": "no: they make a turn or a slide", "w": ["yes, across the line midway", "yes, when the lines are parallel", "yes, when the lines cross"], "why": "Lines that cross give a turn, and parallel lines give a slide. It takes a third flip to flip again."}, {"q": "Is a flip after a flip the same in either order?", "a": "not in general: the two orders give a turn and its undo", "w": ["no: never", "yes, always", "yes, whenever the lines cross"], "why": "For lines at right angles both orders give the half turn, which undoes itself. For most pairs of lines they differ."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20f"]=(C["20f"]||[]).concat([{"q": "Why must the three anchors not lie on one line?", "a": "a point and its flip across that line have the same three distances", "w": ["two of them would then be the same point", "a line has no distances", "no reason: any three points will do"], "why": "The flip across the line keeps all three anchors in place."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20g"]=(C["20g"]||[]).concat([{"q": "Does an even number of flips do nothing?", "a": "not always: two flips make a turn or a slide", "w": ["yes", "yes, when the lines cross", "no: it makes a flip"], "why": "An even number of flips keeps D. Keeping D is less than doing nothing."}, {"q": "What does a stretch by k do to D?", "a": "it multiplies D by k²", "w": ["it keeps D", "it changes the sign of D", "it multiplies D by k"], "why": "Each of the two displacements in D is multiplied by k."}, {"q": "Can a string of 4 flips be the same move as a string of 3 flips?", "a": "no: the first keeps D and the second changes its sign", "w": ["yes", "only when the lines are parallel", "yes, when lines repeat"], "why": "Flip-parity: no string of an even number of flips equals a string of an odd number."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20h"]=(C["20h"]||[]).concat([{"q": "Which of these does every stretch keep?", "a": "the ratio of any two lengths", "w": ["D", "every length", "every area"], "why": "A stretch by k multiplies every length by k, so the k cancels in a ratio. It multiplies D and areas by k²."}, {"q": "In the geometry of the slides alone, is the direction of a side a fact?", "a": "yes: a slide keeps every displacement", "w": ["no: only lengths are facts", "no: a fact must hold in every geometry", "yes: every statement is a fact there"], "why": "A turn changes directions, so in the geometry of the slides and turns it is no longer a fact."}, {"q": "Are similar figures congruent?", "a": "not always: take the 3, 4, 5 and the 6, 8, 10 triangles", "w": ["yes, when they are triangles", "no: never", "yes"], "why": "The geometry of the similarities sorts them together. The geometry of the isometries does not."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["20i"]=(C["20i"]||[]).concat([{"q": "Pulled upright by 2, y = f(x) becomes which?", "a": "y = 2f(x)", "w": ["y = f(x) + 2", "y = f(2x)", "y = f(x/2)"], "why": "(x, y/2) must be on the old graph: y/2 = f(x). y = f(x/2) pulls sideways."}, {"q": "The graph of y = f(x) is slid right by 3. Which equation has it now?", "a": "y = f(x − 3)", "w": ["y = f(x + 3)", "y = f(x) + 3", "y = f(x) − 3"], "why": "The move goes into the equation undone: (x − 3, y) must be on the old graph."}, {"q": "Flipped over the floor, y = f(x) becomes which?", "a": "y = −f(x)", "w": ["x = f(y)", "y = −f(−x)", "y = f(−x)"], "why": "The floor flips y: (x, −y) must be on the old graph. y = f(−x) is the flip over the upright axis."}, {"q": "Pulled sideways by 2, y = f(x) becomes which?", "a": "y = f(x/2)", "w": ["y = f(2x)", "y = f(x − 2)", "y = 2f(x)"], "why": "(x/2, y) must be on the old graph. y = f(2x) squeezes the graph to half its width."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
